function over_budget() {
  const budgets = state.budgets || {};
  const spent = by_category();
  const toCents = (amount) => {
    const n = Number(amount);
    if (!Number.isFinite(n)) return 0;
    const scaled = Number(n + "e2");
    return Math.round(Number.isFinite(scaled) ? scaled : n * 100);
  };
  const result = [];
  for (const category of Object.keys(budgets)) {
    const budgetCents = toCents(budgets[category]);
    const spentCents = toCents(spent[category] === undefined ? 0 : spent[category]);
    if (spentCents > budgetCents) {
      result.push({
        category,
        budget: budgetCents / 100,
        spent: spentCents / 100,
        over: (spentCents - budgetCents) / 100
      });
    }
  }
  result.sort((a, b) => b.over - a.over || (a.category < b.category ? -1 : a.category > b.category ? 1 : 0));
  return result;
}

